<script setup lang="ts">
import type { PagedResponse } from '~/types/api'; import type { Recommendation } from '~/types/domain'; import { resourceRoute } from '~/utils/format'
definePageMeta({layout:'app'});useSeoMeta({title:'Recommendations'});const api=useApi();const {refreshToday,refreshTodayAndNavigation}=useLearningDataInvalidation();const items=ref<Recommendation[]>([]);const loading=ref(true);const status=ref('Active');const generating=ref(false);async function load(){loading.value=true;try{items.value=(await api.get<PagedResponse<Recommendation>>('/recommendations',{status:status.value,page:1,pageSize:50})).items}finally{loading.value=false}}async function generate(){generating.value=true;try{await api.post('/recommendations/generate',{maximumCandidates:100});await Promise.all([load(),refreshTodayAndNavigation()])}finally{generating.value=false}}async function mutate(item:Recommendation,action:'dismiss'|'complete'){await api.post(`/recommendations/${item.recommendationId}/${action}`,{expectedVersion:item.version});await Promise.all([load(),refreshToday()])}watch(status,load);onMounted(load)
</script>
<template><div><CorePageHeader title="Recommendations" description="Convert learning evidence into a concrete next action."><UButton label="Generate" icon="i-lucide-sparkles" :loading="generating" @click="generate" /></CorePageHeader><select v-model="status" class="filter"><option>Active</option><option>Completed</option><option>Dismissed</option><option>Expired</option><option value="">All statuses</option></select><CoreLoadingState v-if="loading" label="Loading recommendations" /><CoreEmptyState v-else-if="!items.length" title="No recommendations in this view" description="Generate recommendations after weak topics have been calculated." /><div v-else class="recommendations"><article v-for="item in items" :key="item.recommendationId"><div class="meta"><CoreStatusBadge :value="item.priority" /><span>{{ item.type }} · score {{ item.priorityScore }}</span></div><h2>{{ item.resourceTitle }}</h2><p>{{ item.resourcePreview || `${item.signalCount} signals indicate ${item.weaknessLevel.toLowerCase()} weakness.` }}</p><div class="reason"><UIcon name="i-lucide-info" /><span>{{ item.signalCount }} signals produced a weakness score of {{ item.weaknessScore }}.</span></div><footer><UButton :to="resourceRoute(item.resourceType,item.resourceId)" label="Open resource" color="neutral" variant="outline" /><template v-if="item.status==='Active'"><UButton label="Dismiss" color="neutral" variant="ghost" @click="mutate(item,'dismiss')" /><UButton label="Complete" @click="mutate(item,'complete')" /></template></footer></article></div></div></template>
<style scoped>.filter{margin-bottom:1rem;padding:.5rem;border:1px solid var(--ui-border);border-radius:.5rem}.recommendations{display:grid;grid-template-columns:repeat(auto-fill,minmax(19rem,1fr));gap:.75rem}.recommendations article{padding:1rem;border:1px solid var(--ui-border);border-radius:.8rem}.meta{display:flex;justify-content:space-between;gap:.5rem;color:var(--ui-text-muted);font-size:.75rem}.recommendations h2{margin:.8rem 0 .3rem;font-weight:700}.recommendations>article>p{min-height:3rem;color:var(--ui-text-muted);font-size:.85rem}.reason{display:flex;gap:.5rem;margin:1rem 0;padding:.7rem;border-radius:.55rem;background:var(--ui-bg-muted);font-size:.78rem}.recommendations footer{display:flex;flex-wrap:wrap;justify-content:end;gap:.4rem}</style>
